function shuffled<T>(items:T[]){const next=[...items];for(let i=next.length-1;i>0;i--){const random=globalThis.crypto?.getRandomValues?globalThis.crypto.getRandomValues(new Uint32Array(1))[0]/4294967296:Math.random(),j=Math.floor(random*(i+1));[next[i],next[j]]=[next[j],next[i]]}return next}
function sameOrder(a:string[],b:string[]){return a.length===b.length&&a.every((x,i)=>x===b[i])}
function charCount(text:string){return [...text.replace(/\s/g,'')].reduce<Record<string,number>>((acc,ch)=>{acc[ch]=(acc[ch]||0)+1;return acc},{})}
function sameCharacters(a:string,b:string){const aa=charCount(a),bb=charCount(b),keys=new Set([...Object.keys(aa),...Object.keys(bb)]);return [...keys].every(k=>aa[k]===bb[k])}
function puzzleShape(count:number){let cols=Math.ceil(Math.sqrt(count));while(cols>1&&count%cols!==0)cols--;return[cols,Math.ceil(count/cols)]}
